}

class Salesperson {
  + Name : string
}

class Contract {
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + Model : string
  + Price : double
  + Options : string
  + DeliveryDate : date
}

class Airplane {
  + SerialNumber : string
  + Model : string
}

Salesperson "1" -- "0..*" Contract
Contract "1" -- "1..*" Acquisition
Acquisition "1" -- "1" Airplane
Airline "1" -- "0..*" Contract
Airline "0..1" o-- "0..*" Airline : daughterOf

@enduml

